    func battleStatusName(_ status: String) -> String {
        switch status {
        case "brn": return t("화상", "Burn", "やけど", "Quemadura", "Brûlure", "Queimadura", "Verbrennung", "Ожог")
        case "par": return t("마비", "Paralysis", "まひ", "Parálisis", "Paralysie", "Paralisia", "Paralyse", "Паралич")
        case "slp": return t("잠듦", "Sleep", "ねむり", "Sueño", "Sommeil", "Sono", "Schlaf", "Сон")
        case "frz": return t("얼음", "Freeze", "こおり", "Congelación", "Gel", "Congelamento", "Gefroren", "Заморозка")
        case "psn": return t("독", "Poison", "どく", "Veneno", "Poison", "Veneno", "Vergiftung", "Отравление")
        case "tox": return t("맹독", "Bad poison", "もうどく", "Veneno grave", "Poison grave", "Envenenamento grave", "Schwere Vergiftung", "Сильное отравление")
        default: return t("정상", "Healthy", "正常", "Sano", "En bonne santé", "Saudável", "Gesund", "Здоров")
        }
    }
